-- Migration de autenticacao inicial do ERPell (Etapa 5).
--
-- Cria o minimo necessario para autenticacao: empresa (tenant) e usuario.
-- O usuario nasce vinculado a uma empresa (DEC-016), sem implementar
-- multiempresa avancado nem o modulo Empresa completo.
--
-- Padrao de chave primaria interna: BIGINT GENERATED BY DEFAULT AS IDENTITY (DEC-015).
-- A aplicacao nunca fornece o id manualmente; o banco sempre gera.

-- Empresa (tenant): estrutura minima para suportar a autenticacao inicial.
CREATE TABLE empresa (
    id            BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome          VARCHAR(150) NOT NULL,
    ativo         BOOLEAN      NOT NULL DEFAULT true,
    criado_em     TIMESTAMP    NOT NULL DEFAULT now(),
    atualizado_em TIMESTAMP
);

-- Usuario: sempre vinculado a uma empresa.
-- senha_hash com VARCHAR(72): comporta o hash BCrypt (60 caracteres) com folga.
CREATE TABLE usuario (
    id            BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    empresa_id    BIGINT       NOT NULL,
    nome          VARCHAR(150) NOT NULL,
    email         VARCHAR(180) NOT NULL,
    senha_hash    VARCHAR(72)  NOT NULL,
    perfil        VARCHAR(30)  NOT NULL,
    ativo         BOOLEAN      NOT NULL DEFAULT true,
    criado_em     TIMESTAMP    NOT NULL DEFAULT now(),
    atualizado_em TIMESTAMP,
    CONSTRAINT fk_usuario_empresa FOREIGN KEY (empresa_id) REFERENCES empresa (id),
    -- Unicidade de e-mail global nesta fase (simples). Se futuramente o produto
    -- precisar de e-mail unico por empresa, revisar esta constraint em migration propria.
    CONSTRAINT uq_usuario_email UNIQUE (email)
);

-- Indice para acelerar o lookup por empresa (consultas futuras por tenant).
CREATE INDEX idx_usuario_empresa ON usuario (empresa_id);
